public class BoxTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("new Box(2.5, 4.0).area()", 10.0, new Box(2.5, 4.0).area());
        check("new Box(7.0, 1.0).area()", 7.0, new Box(7.0, 1.0).area());
        Sized s = new Box(1.5, 2.0);
        check("area() through a Sized reference", 3.0, s.area());
        Box sq = Box.square(3.0);
        check("square(3.0).area()", 9.0, sq == null ? null : sq.area());
        check("square(3.0).width()", 3.0, sq == null ? null : sq.width());
        check("square(3.0).height()", 3.0, sq == null ? null : sq.height());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

